typedef struct {
  int *arr;
  int size;
  int top[3];
} TripleInOne;

TripleInOne *tripleInOneCreate(int stackSize) {
  TripleInOne *obj = (TripleInOne *)malloc(sizeof(TripleInOne));
  obj->arr = (int *)malloc(sizeof(int) * 3 * (stackSize > 0 ? stackSize : 1));
  obj->size = stackSize;
  obj->top[0] = obj->top[1] = obj->top[2] = 0;
  return obj;
}

void tripleInOnePush(TripleInOne *obj, int stackNum, int value) {
  if (obj->top[stackNum] < obj->size) {
    obj->arr[stackNum * obj->size + obj->top[stackNum]++] = value;
  }
}

int tripleInOnePop(TripleInOne *obj, int stackNum) {
  if (obj->top[stackNum] == 0) return -1;
  return obj->arr[stackNum * obj->size + --obj->top[stackNum]];
}

int tripleInOnePeek(TripleInOne *obj, int stackNum) {
  if (obj->top[stackNum] == 0) return -1;
  return obj->arr[stackNum * obj->size + obj->top[stackNum] - 1];
}

bool tripleInOneIsEmpty(TripleInOne *obj, int stackNum) {
  return obj->top[stackNum] == 0;
}

void tripleInOneFree(TripleInOne *obj) {
  free(obj->arr);
  free(obj);
}

class TripleInOne {
  vector<int> arr;
  int size;
  int top[3];

public:
  TripleInOne(int stackSize) : arr(3 * stackSize), size(stackSize) {
    top[0] = top[1] = top[2] = 0;
  }
  void push(int stackNum, int value) {
    if (top[stackNum] < size) arr[stackNum * size + top[stackNum]++] = value;
  }
  int pop(int stackNum) {
    if (top[stackNum] == 0) return -1;
    return arr[stackNum * size + --top[stackNum]];
  }
  int peek(int stackNum) {
    if (top[stackNum] == 0) return -1;
    return arr[stackNum * size + top[stackNum] - 1];
  }
  bool isEmpty(int stackNum) { return top[stackNum] == 0; }
};

type TripleInOne struct {
	arr  []int
	size int
	top  [3]int
}

func Constructor(stackSize int) TripleInOne {
	return TripleInOne{arr: make([]int, 3*stackSize), size: stackSize}
}

func (t *TripleInOne) Push(stackNum int, value int) {
	if t.top[stackNum] < t.size {
		t.arr[stackNum*t.size+t.top[stackNum]] = value
		t.top[stackNum]++
	}
}

func (t *TripleInOne) Pop(stackNum int) int {
	if t.top[stackNum] == 0 {
		return -1
	}
	t.top[stackNum]--
	return t.arr[stackNum*t.size+t.top[stackNum]]
}

func (t *TripleInOne) Peek(stackNum int) int {
	if t.top[stackNum] == 0 {
		return -1
	}
	return t.arr[stackNum*t.size+t.top[stackNum]-1]
}

func (t *TripleInOne) IsEmpty(stackNum int) bool {
	return t.top[stackNum] == 0
}

class TripleInOne {
  private List<Integer> arr;
  private int size;
  private int[] top = new int[3];

  public TripleInOne(int stackSize) {
    this.size = stackSize;
    this.arr = new ArrayList<>();
    for (int i = 0; i < 3 * stackSize; i++) arr.add(0);
  }

  public void push(int stackNum, int value) {
    if (top[stackNum] < size) arr.set(stackNum * size + top[stackNum]++, value);
  }

  public int pop(int stackNum) {
    if (top[stackNum] == 0) return -1;
    return arr.get(stackNum * size + --top[stackNum]);
  }

  public int peek(int stackNum) {
    if (top[stackNum] == 0) return -1;
    return arr.get(stackNum * size + top[stackNum] - 1);
  }

  public boolean isEmpty(int stackNum) {
    return top[stackNum] == 0;
  }
}

class TripleInOne:
    def __init__(self, stackSize: int):
        self.size = stackSize
        self.arr = [0] * (3 * stackSize)
        self.top = [0, 0, 0]

    def push(self, stackNum: int, value: int) -> None:
        if self.top[stackNum] < self.size:
            self.arr[stackNum * self.size + self.top[stackNum]] = value
            self.top[stackNum] += 1

    def pop(self, stackNum: int) -> int:
        if self.top[stackNum] == 0:
            return -1
        self.top[stackNum] -= 1
        return self.arr[stackNum * self.size + self.top[stackNum]]

    def peek(self, stackNum: int) -> int:
        if self.top[stackNum] == 0:
            return -1
        return self.arr[stackNum * self.size + self.top[stackNum] - 1]

    def isEmpty(self, stackNum: int) -> bool:
        return self.top[stackNum] == 0

impl TripleInOne {
  pub fn new(stack_size: i32) -> Self {
    let size = stack_size as usize;
    TripleInOne {
      arr: vec![0; 3 * size],
      size,
      top: [0, 0, 0],
    }
  }

  pub fn push(&mut self, stack_num: i32, value: i32) {
    let s = stack_num as usize;
    if self.top[s] < self.size {
      self.arr[s * self.size + self.top[s]] = value;
      self.top[s] += 1;
    }
  }

  pub fn pop(&mut self, stack_num: i32) -> i32 {
    let s = stack_num as usize;
    if self.top[s] == 0 {
      return -1;
    }
    self.top[s] -= 1;
    self.arr[s * self.size + self.top[s]]
  }

  pub fn peek(&self, stack_num: i32) -> i32 {
    let s = stack_num as usize;
    if self.top[s] == 0 {
      return -1;
    }
    self.arr[s * self.size + self.top[s] - 1]
  }

  pub fn is_empty(&self, stack_num: i32) -> bool {
    self.top[stack_num as usize] == 0
  }
}

class TripleInOne {
  private arr: number[];
  private size: number;
  private top: number[] = [0, 0, 0];

  constructor(stackSize: number) {
    this.size = stackSize;
    this.arr = new Array(3 * stackSize).fill(0);
  }

  push(stackNum: number, value: number): void {
    if (this.top[stackNum] < this.size) {
      this.arr[stackNum * this.size + this.top[stackNum]++] = value;
    }
  }

  pop(stackNum: number): number {
    if (this.top[stackNum] === 0) return -1;
    return this.arr[stackNum * this.size + --this.top[stackNum]];
  }

  peek(stackNum: number): number {
    if (this.top[stackNum] === 0) return -1;
    return this.arr[stackNum * this.size + this.top[stackNum] - 1];
  }

  isEmpty(stackNum: number): boolean {
    return this.top[stackNum] === 0;
  }
}
